// HasJobs applies the HasEdge predicate on the "jobs" edge.
func HasJobs() predicate.DiscoverySource {
	return predicate.DiscoverySource(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.O2M, false, JobsTable, JobsColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasJobsWith applies the HasEdge predicate on the "jobs" edge with a given conditions (other predicates).
func HasJobsWith(preds ...predicate.DiscoveryJob) predicate.DiscoverySource {
	return predicate.DiscoverySource(func(s *sql.Selector) {
		step := newJobsStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.DiscoverySource) predicate.DiscoverySource {
	return predicate.DiscoverySource(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.DiscoverySource) predicate.DiscoverySource {
	return predicate.DiscoverySource(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.DiscoverySource) predicate.DiscoverySource {
	return predicate.DiscoverySource(sql.NotPredicates(p))
}
